DO $$DECLARE c uuid:=current_setting('erp.reversal.cafe')::uuid;advance uuid:=current_setting('report.test.advance')::uuid;invoice uuid:=current_setting('report.test.invoice')::uuid;customer uuid:=current_setting('report.test.customer')::uuid;owner_id uuid;other_id uuid;branch_a uuid:=gen_random_uuid();branch_b uuid:=gen_random_uuid();name text;r jsonb;denied boolean;actual_remaining numeric;ordinary numeric;BEGIN
 SELECT owner_user_id INTO owner_id FROM public.cafes WHERE id=c;SELECT id INTO other_id FROM public.profiles WHERE id<>owner_id AND status='active' AND role<>'platform_admin' ORDER BY created_at LIMIT 1;
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'role','authenticated')::text,true);PERFORM set_config('erp.branch_expected','',true);
 SELECT p.name INTO name FROM public.bf_parties p WHERE cafe_id=c AND id=customer;actual_remaining:=erp_settings_private.advance_available(c,advance);ordinary:=brand_finance_private.customer_credit_balance(c,customer);
 PERFORM pg_temp.report_assert((SELECT count(*)=2 FROM erp_reports_private.catalog WHERE id IN('sales','customer-sales') AND source='business-sales'),'business catalogs select new source');
 PERFORM pg_temp.report_assert((SELECT count(*)>0 FROM erp_reports_private.catalog WHERE source='sales' AND id NOT IN('sales','customer-sales')),'tax and payment position retain canonical sales source');
 PERFORM pg_temp.report_assert(EXISTS(SELECT 1 FROM erp_reports_private.catalog WHERE source='customer-credits' AND definition->>'basis' LIKE '%الحالي%'),'customer balance explicitly current not historical');
 PERFORM pg_temp.report_assert((SELECT columns=(SELECT columns FROM erp_reports_private.sources WHERE id='sales') FROM erp_reports_private.sources WHERE id='business-sales'),'business source clones canonical columns');
 INSERT INTO public.branches(id,cafe_id,name,active) VALUES(branch_a,c,'COMMERCIAL-REPORT-PROBE A',true),(branch_b,c,'COMMERCIAL-REPORT-PROBE B',true);
 INSERT INTO public.erp_branch_scopes(cafe_id,user_id,branch_id,revision) VALUES(c,owner_id,branch_a,1) ON CONFLICT(cafe_id,user_id) DO UPDATE SET branch_id=excluded.branch_id,revision=erp_branch_scopes.revision+1;
 INSERT INTO public.erp_branch_documents(cafe_id,document_id,branch_id) VALUES(c,advance,branch_b) ON CONFLICT(document_id) DO UPDATE SET branch_id=excluded.branch_id;
 r:=pg_temp.report_query(c,'customer-credits',name);PERFORM pg_temp.report_assert(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'rows')x WHERE x->>'id'='advance-invoice:'||advance::text),'other branch cannot read advance available row');
 r:=pg_temp.report_query(c,'sales',name);PERFORM pg_temp.report_assert(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'rows')x WHERE x->>'id'=advance::text),'canonical tax invoice reader preserves existing branch filter');
 UPDATE public.erp_branch_scopes SET branch_id=branch_b,revision=revision+1 WHERE cafe_id=c AND user_id=owner_id;
 r:=pg_temp.report_query(c,'customer-credits',name);PERFORM pg_temp.report_assert(EXISTS(SELECT 1 FROM jsonb_array_elements(r->'rows')x WHERE x->>'id'='advance-invoice:'||advance::text AND(x->>'remaining')::numeric=actual_remaining),'matching branch can read genuine advance row');
 PERFORM set_config('request.jwt.claim.sub',other_id::text,true);denied:=false;BEGIN PERFORM pg_temp.report_query(c,'business-sales');EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;PERFORM pg_temp.report_assert(denied,'foreign actor cannot read business source');
 INSERT INTO public.bf_staff(cafe_id,user_id,name,role,active) VALUES(c,other_id,'COMMERCIAL-REPORT-PROBE cashier','cashier',true);
 denied:=false;BEGIN PERFORM pg_temp.report_query(c,'customer-credits');EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;PERFORM pg_temp.report_assert(denied,'cashier cannot read customer advance balances');
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);denied:=false;BEGIN PERFORM pg_temp.report_query('d3000000-0000-4000-8000-000000000002','business-sales');EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;PERFORM pg_temp.report_assert(denied,'owner cannot read foreign tenant reports');
 PERFORM pg_temp.report_assert(NOT has_function_privilege('authenticated','erp_reports_private.financial_facts(uuid,text,date,date)','EXECUTE') AND NOT has_function_privilege('anon','public.erp_report_run(uuid,jsonb)','EXECUTE'),'report private source and anonymous gates retained');
END$$;
